import Cocoa
extension Delegate {
 var styledPoem:String{poetryStyle.text(title:poemTitle,author:poemAuthor,body:poemBody,category:poemCategory)}
 func poetryLayer(size:NSSize,scale:CGFloat)->CALayer{let layer=CALayer();layer.frame=CGRect(origin:.zero,size:size);layer.contents=poetryStyle.textImage(size:size,title:poemTitle,author:poemAuthor,body:poemBody,category:poemCategory).cgImage(forProposedRect:nil,context:nil,hints:nil);layer.contentsScale=scale;return layer}
 func refreshVideoText(){for layer in videoTexts{let size=layer.superlayer?.bounds.size ?? .zero;layer.frame=CGRect(origin:.zero,size:size);layer.contents=poetryStyle.textImage(size:size,title:poemTitle,author:poemAuthor,body:poemBody,category:poemCategory).cgImage(forProposedRect:nil,context:nil,hints:nil)}}
 func composedPoetry()->Data?{guard let image=lastImage else{return nil};let size=NSSize(width:2560,height:1600);let result=NSImage(size:size);result.lockFocus();let ratio=max(size.width/image.size.width,size.height/image.size.height);image.draw(in:NSRect(x:(size.width-image.size.width*ratio)/2,y:(size.height-image.size.height*ratio)/2,width:image.size.width*ratio,height:image.size.height*ratio));let scale=size.width/(NSScreen.screens.first?.frame.width ?? 1440);poetryStyle.textImage(size:size,title:poemTitle,author:poemAuthor,body:poemBody,category:poemCategory,scale:scale).draw(in:NSRect(origin:.zero,size:size));result.unlockFocus();guard let tiff=result.tiffRepresentation else{return nil};return NSBitmapImageRep(data:tiff)?.representation(using:.png,properties:[:])}
 @objc func choosePoetryFont(){restOverlay.finish();closeInlinePanel();let manager=NSFontManager.shared;manager.target=self;manager.action=#selector(changeFont(_:));manager.setSelectedFont(poetryStyle.font,isMultiple:false);NSApp.activate(ignoringOtherApps:true);if let panel=manager.fontPanel(true){panel.level = .floating;panel.makeKeyAndOrderFront(nil)}}
 @objc func changeFont(_ sender:NSFontManager){let font=sender.convert(poetryStyle.font);applySetting("fontName",font.fontName);applySetting("size",String(Int(font.pointSize)))}
}
